const pipelineConnections = `-- name: PipelineConnections :many
SELECT id, account_id, name, revision, ciphertext, identity, created_at FROM data_pipeline_connections WHERE account_id=$1::text::uuid ORDER BY name LIMIT $2
`

type PipelineConnectionsParams struct {
	AccountID string
	PageLimit int32
}

func (q *Queries) PipelineConnections(ctx context.Context, db DBTX, arg PipelineConnectionsParams) ([]DataPipelineConnection, error) {
	rows, err := db.Query(ctx, pipelineConnections, arg.AccountID, arg.PageLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []DataPipelineConnection{}
	for rows.Next() {
		var i DataPipelineConnection
		if err := rows.Scan(
			&i.ID,
			&i.AccountID,
			&i.Name,
			&i.Revision,
			&i.Ciphertext,
			&i.Identity,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

