const pipelineRequestTableCancellation = `-- name: PipelineRequestTableCancellation :execrows
UPDATE data_pipelines SET revision=revision+1,retry_at=clock_timestamp(),
 schema_change=jsonb_set(schema_change,'{Cancellation}',jsonb_build_object('Table',$1::text,'RequestID',$2::text,'State','requested','Retention','retain_private'))
WHERE account_id=$3::text::uuid AND id=$4::text::uuid AND revision=$5
 AND desired_state='running' AND state IN ('live','copying','blocked')
 AND schema_approval=schema_change->>'ID' AND schema_change->>'State'<>'complete'
 AND jsonb_array_length(coalesce(schema_change->'Before','[]'))>0 AND schema_change->'AddedTables' ? $1::text
 AND coalesce(schema_change->'Cancellation'->>'State','')<>'approved'
 AND (coalesce(schema_change->'Recovery'->>'State','')<>'approved' OR schema_change->'Recovery'->>'Stage'='verifying' OR schema_change->'Recovery'->>'Table'=$1::text)
 AND observed_revision=revision AND observed_at>clock_timestamp()-($6::bigint*interval '1 second')
`

type PipelineRequestTableCancellationParams struct {
	TableName     string
	RequestID     string
	AccountID     string
	ID            string
	Revision      int64
	MaxAgeSeconds int64
}

func (q *Queries) PipelineRequestTableCancellation(ctx context.Context, db DBTX, arg PipelineRequestTableCancellationParams) (int64, error) {
	result, err := db.Exec(ctx, pipelineRequestTableCancellation,
		arg.TableName,
		arg.RequestID,
		arg.AccountID,
		arg.ID,
		arg.Revision,
		arg.MaxAgeSeconds,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const pipelineRequestTableRecovery = `-- name: PipelineRequestTableRecovery :execrows
UPDATE data_pipelines SET revision=revision+1,retry_at=clock_timestamp(),
 schema_change=jsonb_set(schema_change,'{Recovery}',CASE WHEN $1::text='live'
 THEN (schema_change->'Recovery')||jsonb_build_object('State','requested','ID','','Stage','quarantined')
 ELSE jsonb_build_object('Table',$2::text,'Kind',$1::text,'State','requested') END)
WHERE account_id=$3::text::uuid AND id=$4::text::uuid AND revision=$5
 AND desired_state='running' AND state='blocked'
 AND schema_approval=schema_change->>'ID' AND schema_change->>'State'<>'complete' AND (schema_change->>'Supported')::boolean
 AND (schema_change->'AddedTables' ? $2::text OR
 ($1::text='live' AND schema_change->'Recovery'->>'Kind'='live' AND tables=schema_change->'RequestedTables' AND tables ? $2::text AND schema_change->'Recovery'->>'Table'=$2::text))
 AND coalesce(schema_change->'Cancellation'->>'State','') NOT IN ('requested','pending','approved')
 AND (coalesce(schema_change->'Recovery'->>'State','') NOT IN ('requested','pending','approved') OR schema_change->'Recovery'->>'Stage'='verifying')
 AND (($1::text='live' AND schema_change->'Recovery'->>'Kind'='live' AND reason IN ('live_table_mismatch','replica_mismatch')
 AND verification_progress->>'State'='mismatch' AND verification_progress->>'Table'=$2::text)
 OR ($1::text='' AND coalesce(schema_change->'Recovery'->>'Kind','')<>'live' AND reason='replica_mismatch' AND verification_progress->>'State'='mismatch' AND verification_progress->>'Table'=$2::text)
 OR ($1::text='copy' AND reason IN ('table_copy_stalled','table_addition_tracking_lost')
 AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(schema_change->'Copies','[]')) c WHERE c->>'Table'=$2::text
 AND coalesce(c->>'NativeState','')<>'r' AND (coalesce((c->>'Stalled')::boolean,false) OR c->>'Phase'='missing'))
 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(schema_change->'Copies','[]')) other_copy WHERE other_copy->>'Table'<>$2::text AND coalesce(other_copy->>'NativeState','')='')))
 AND coalesce((schema_change->>'Retry')::integer,0)<$6::integer
 AND observed_revision=revision AND observed_at>clock_timestamp()-($7::bigint*interval '1 second')
`

type PipelineRequestTableRecoveryParams struct {
	Kind          string
	TableName     string
	AccountID     string
	ID            string
	Revision      int64
	MaxRetries    int32
	MaxAgeSeconds int64
}

func (q *Queries) PipelineRequestTableRecovery(ctx context.Context, db DBTX, arg PipelineRequestTableRecoveryParams) (int64, error) {
	result, err := db.Exec(ctx, pipelineRequestTableRecovery,
		arg.Kind,
		arg.TableName,
		arg.AccountID,
		arg.ID,
		arg.Revision,
		arg.MaxRetries,
		arg.MaxAgeSeconds,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

